/**
 * Table.Header: a column header, a `<th>`, with the sort control when the column sorts.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/table.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'

import { Icon, claimSlot, scope, type Defaults } from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/table.module.css'

export interface TableHeaderProps {
  children?: JSX.Element
  numeric?: boolean
  onSort?: () => void
  sortable?: boolean
  /**
   * Controlled by the caller: Table shows the sort control, and DataTable sorts.
   */
  sortDirection?: 'asc' | 'desc'
}

/** Table.Header: a column header, a `<th>`, with the sort control when the column sorts. */
export default function TableHeader(given: TableHeaderProps): JSX.Element {
  const props = mergeProps(
    { sortable: false, numeric: false } as Defaults<TableHeaderProps, 'sortable' | 'numeric'>,
    claimSlot(given),
  )
  return scope(() => {
    return (
      <th
        class={styles.header}
        scope="col"
        data-sortable={props.sortable ? '' : undefined}
        data-numeric={props.numeric ? '' : undefined}
        aria-sort={
          props.sortDirection === 'asc'
            ? 'ascending'
            : props.sortDirection === 'desc'
              ? 'descending'
              : undefined
        }
      >
        {props.sortable ? (
          <button class={styles.sortButton} type="button" onclick={() => props.onSort?.()}>
            {props.children}
            <span
              class={styles.sortIcon}
              data-active={props.sortDirection !== undefined ? '' : undefined}
            >
              <Icon
                name={
                  props.sortDirection === 'asc'
                    ? 'sort-asc'
                    : props.sortDirection === 'desc'
                      ? 'sort-desc'
                      : 'sort'
                }
                size="sm"
              />
            </span>
          </button>
        ) : (
          props.children
        )}
      </th>
    )
  })
}
